//! 🧪️ Fresh native read bytes initialize only under the current finite copy and work bank.
use super::*;
#[test]
fn native_read_buffer_funds_each_initialized_prefix_and_preserves_cached_bytes(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🎟️original/payload.json")).unwrap();let profile=&law["source"];let policy=&law["buffer"];
 for length in policy["lengths"].as_array().unwrap(){let length=length.as_u64().unwrap()as usize;for body in policy["bodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;let mut buffer=NativeReadBuffer::new();let mut cpu=profile["fuel"].as_u64().unwrap();let mut copy=profile["grant"]["maximumCopyBytes"].as_u64().unwrap()as usize;let mut initialized=0;
  for turn in 0..law["maximumTurns"].as_u64().unwrap(){if buffer.initialized_len()>=length{break}let d=buffer.initialization_demand(length,body).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_depth:d.depth,..Default::default()};assert!(g.maximum_copy_bytes<=copy&&g.maximum_items as u64<=cpu);
   for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||buffer.initialize_prefix(length,body,denied));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(result.work,0);assert_eq!(result.result.unwrap().progress(),Default::default());assert_eq!(buffer.initialized_len(),initialized)}
   let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||buffer.initialize_prefix(length,body,g));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(result.work,1);cpu-=result.work;let p=result.result.unwrap().progress();assert!(p.fits(g));assert_eq!(p.retained_capacity_bytes,0);assert_eq!(p.released_bytes,0);copy-=p.copied_bytes;initialized+=p.copied_bytes;assert_eq!(buffer.initialized_len(),initialized);assert!(turn<16383);
  }
  assert_eq!(buffer.initialized_prefix(length).unwrap(),vec![0;length]);assert_eq!(serde_json::to_value(buffer.initialized_prefix(length).unwrap()).unwrap(),serde_json::json!(vec![0;length]));buffer.initialized_prefix_mut(length).unwrap().fill(7);let(cached,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||buffer.initialize_prefix(length,body,Default::default()));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(cached.work,policy["cachedWork"].as_u64().unwrap());assert_eq!(cached.result.unwrap().progress(),Default::default());assert_eq!(buffer.initialized_prefix(length).unwrap(),vec![7;length]);assert_eq!(initialized,length);
 }}
}

#[test]
fn native_read_buffer_original_backing_survives_moves_and_releases_under_exact_authority(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🎟️original/payload.json")).unwrap();let policy=&law["stableBuffer"];let mut cpu=law["source"]["fuel"].as_u64().unwrap();let mut capacity=law["source"]["grant"]["maximumCapacityBytes"].as_u64().unwrap()as usize;let mut release=law["source"]["grant"]["maximumReleaseBytes"].as_u64().unwrap()as usize;let mut output=None;
 let d=NativeReadBuffer::birth_demand();let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:d.capacity_bytes,maximum_depth:d.depth,..Default::default()};assert!(d.capacity_bytes<=capacity);
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||NativeReadBuffer::admit(&mut output,denied));assert_eq!(turn.work,policy["deniedWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(output.is_none())}
 let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||NativeReadBuffer::admit(&mut output,g));assert_eq!(turn.work,policy["birthWork"].as_u64().unwrap());cpu-=turn.work;let p=turn.result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,0));assert_eq!(p.retained_capacity_bytes,d.capacity_bytes);capacity-=p.retained_capacity_bytes;
 let pointer=output.as_ref().unwrap().as_ref()as*const NativeReadBuffer;let mut moved=output.take();assert_eq!(moved.as_ref().unwrap().as_ref()as*const NativeReadBuffer,pointer);
 let turn=NativeReadBuffer::admit(&mut moved,Default::default());assert_eq!(turn.work,policy["cachedWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress(),Default::default());
 let d=NativeReadBuffer::release_demand(&moved);assert!(d.release_bytes<=release);let g=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth,..Default::default()};
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||NativeReadBuffer::release(&mut moved,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(moved.as_ref().unwrap().as_ref()as*const NativeReadBuffer,pointer)}
 let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||NativeReadBuffer::release(&mut moved,g));assert_eq!(turn.work,policy["releaseWork"].as_u64().unwrap());cpu-=turn.work;let p=turn.result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,d.release_bytes));assert_eq!(p.released_bytes,d.release_bytes);release-=p.released_bytes;assert!(moved.is_none());let cached=NativeReadBuffer::release(&mut moved,Default::default());assert_eq!(cached.work,0);assert_eq!(cached.result.unwrap().progress(),Default::default());assert_eq!(capacity,release);assert_eq!(cpu,law["source"]["fuel"].as_u64().unwrap()-2);
}
